-- ========================================================


function SingleDirectionMove:__init( movePeriod_ )
    if isNull(movePeriod_) then 
        movePeriod_ = 2.0
    end 

    self.elapsedTime = 0
    self.haldPeriod = movePeriod_ * 0.8 -- 从0到1 的时长
    ---
    self.startVal = 0.0
    self.endVal = 1.0 
    self.currentVal = self.startVal    
end


-- 需手动调用 Delete()
function SingleDirectionMove:__delete()
end

---@return number 
function SingleDirectionMove:SetUpdate()

    -- 计算每帧的时间增量  
    self.elapsedTime = self.elapsedTime + Time.deltaTime

    -- 计算动画进度  
    local progress = self.elapsedTime / self.haldPeriod

    -- 使用缓动函数计算当前进度  
    local easedProgress = SingleDirectionMove._EaseInOutSine( Mathf.Clamp01(progress) )  -- [0f,1f]

    -- 更新目标位置  
    self.currentVal = Mathf.Lerp( self.startVal, self.endVal, easedProgress ) 

    -- 检查是否需要反转方向  
    if progress >= 1.25  then   -- 在尾端等上 0.25 个时间单位
        self.elapsedTime = 0
    end
    return self.currentVal
end


----------------------------------------------------------


function SingleDirectionMove:SetMovePeriod( movePeriod_ ) 
    if type(movePeriod_)=="number" and movePeriod_ > 0.0 then 
        self.haldPeriod = checkNumber(movePeriod_) * 0.5
        if self.haldPeriod < 0.001 then 
            printError("设置的参数不能太小: "..tostring(movePeriod_))
            self.haldPeriod = 1
        end 
    else 
        printError("参数异常: "..tostring(movePeriod_))
    end 
end



-- ret: [0f,1f]
-- 这么拗口地实现是为了保证在初始阶段, 一定先从 start 移动向 end;
function SingleDirectionMove._EaseInOutSine( t )
    return -(Mathf.Cos(Mathf.PI * t) - 1.0) / 2.0  
end



return SingleDirectionMove
